 for(const event of events){const person=event.person==='C'?'C':'J',day=Math.max(1,Math.min(days,Number(event.plotDay)||1)),amount=Number(event.amount)||0;if(event.type==='balance-adjustment')manual[person][day]=Math.round((manual[person][day]+amount)*100)/100;else{const bucket=event.checked&&day<=today?actual:planned;bucket[person][day]=Math.round((bucket[person][day]+amount)*100)/100}}
