 const breakdownRow=x=>`<article class="breakdown-row"><div class="breakdown-top"><strong>${esc(x.name)}</strong><b>${x.retained>0?'+':''}${eur(x.retained)}</b></div><div class="breakdown-meta"><span>${esc(x.party||'—')} · ${esc(x.status||'—')}</span>${x.shares?`<span>Part Julien ${eur(x.shares.J)} · Carla ${eur(x.shares.C)} · montant signé ${x.retained>0?'+':''}${eur(x.retained)}</span>`:`<span>Brut ${eur(x.gross)} · retenu ${eur(x.retained)}</span>`}</div></article>`;
